export interface Constellation {
  id: number;
  name: string;
  stars: string[];
}

export interface CreateConstellation {
  name: string;
  stars: readonly string[];
}

export interface UpdateConstellation {
  name?: string;
  stars?: readonly string[];
}

function normalizeName(value: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError("Name must be non-empty.");
  }
  return value.trim();
}

function normalizeStars(values: readonly string[]): string[] {
  if (!Array.isArray(values) || values.length === 0) {
    throw new TypeError("At least one star is required.");
  }
  const stars = values.map(normalizeName);
  if (new Set(stars).size !== stars.length) {
    throw new TypeError("Star names must be unique.");
  }
  return stars;
}

function copy(value: Constellation): Constellation {
  return { id: value.id, name: value.name, stars: value.stars };
}

export class ConstellationStore {
  private readonly values: Constellation[] = [];
  private nextId = 1;

  findAll(): Constellation[] {
    return this.values.map(copy);
  }

  findOne(id: number): Constellation {
    return copy(this.require(id));
  }

  create(input: CreateConstellation): Constellation {
    const name = normalizeName(input.name);
    const stars = normalizeStars(input.stars);
    const value: Constellation = {
      id: this.nextId,
      name,
      stars,
    };
    this.nextId += 1;
    this.values.push(value);
    return copy(value);
  }

  update(id: number, input: UpdateConstellation): Constellation {
    const value = this.require(id);
    const name = input.name === undefined ? undefined : normalizeName(input.name);
    const stars = input.stars === undefined ? undefined : normalizeStars(input.stars);
    if (name !== undefined) value.name = name;
    if (stars !== undefined) value.stars = stars;
    return copy(value);
  }

  remove(id: number): Constellation {
    const value = this.require(id);
    this.values.splice(this.values.indexOf(value), 1);
    return copy(value);
  }

  private require(id: number): Constellation {
    if (!Number.isInteger(id) || id < 1) {
      throw new RangeError("Invalid constellation ID.");
    }
    const value = this.values.find((candidate) => candidate.id === id);
    if (value === undefined) {
      throw new RangeError("Constellation not found.");
    }
    return value;
  }
}

