import { ConstellationStore, CreateConstellation } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
}
function throws(fn: () => unknown, kind: new (...args: any[]) => Error, message: string): void {
  let caught: unknown;
  try { fn(); } catch (error) { caught = error; }
  assert(caught instanceof kind, message);
}

const store = new ConstellationStore();
deepEqual(store.findAll(), [], "empty repository");
for (const id of [0, -1, 1.5, Number.NaN, Number.POSITIVE_INFINITY]) {
  throws(() => store.findOne(id), RangeError, `invalid ID ${String(id)}`);
  throws(() => store.update(id, {}), RangeError, `invalid update ID ${String(id)}`);
  throws(() => store.remove(id), RangeError, `invalid remove ID ${String(id)}`);
}
throws(() => store.findOne(1), RangeError, "absent find");

const stars = ["  Betelgeuse ", "Rigel  "];
const input: CreateConstellation = { name: "  Orion  ", stars };
const created = store.create(input);
deepEqual(created, { id: 1, name: "Orion", stars: ["Betelgeuse", "Rigel"] }, "creation trims content");
stars[0] = "input mutation";
created.name = "result mutation";
created.stars[1] = "result star mutation";
deepEqual(store.findOne(1), { id: 1, name: "Orion", stars: ["Betelgeuse", "Rigel"] }, "create input and output detached");

const second = store.create({ name: "Lyra", stars: ["Vega"] });
equal(second.id, 2, "sequential ID");
const all = store.findAll();
deepEqual(all.map((item) => item.id), [1, 2], "creation order");
all[0].stars.push("Aliased");
all.splice(1, 1);
deepEqual(store.findAll().map((item) => item.stars), [["Betelgeuse", "Rigel"], ["Vega"]], "findAll is deeply detached");

const emptyUpdate = store.update(1, {});
deepEqual(emptyUpdate, { id: 1, name: "Orion", stars: ["Betelgeuse", "Rigel"] }, "empty update");
const updateStars = ["  Bellatrix", "Saiph  "];
const updated = store.update(1, { name: "  Orion Major ", stars: updateStars });
deepEqual(updated, { id: 1, name: "Orion Major", stars: ["Bellatrix", "Saiph"] }, "supplied fields updated and trimmed");
updateStars[0] = "mutated input";
updated.stars[0] = "mutated result";
deepEqual(store.findOne(1), { id: 1, name: "Orion Major", stars: ["Bellatrix", "Saiph"] }, "update arrays and result detached");
deepEqual(store.update(1, { name: " Orion Final " }).stars, ["Bellatrix", "Saiph"], "update changes only supplied fields");

const beforeInvalidUpdate = JSON.stringify(store.findOne(1));
throws(() => store.update(1, { stars: ["same", " same "] }), TypeError, "trimmed duplicate stars");
equal(JSON.stringify(store.findOne(1)), beforeInvalidUpdate, "invalid update changes nothing");

const invalidCreates: CreateConstellation[] = [
  { name: "", stars: ["A"] },
  { name: "   ", stars: ["A"] },
  { name: "Valid", stars: [] },
  { name: "Valid", stars: [""] },
  { name: "Valid", stars: ["   "] },
  { name: "Valid", stars: ["A", " A "] },
];
for (const bad of invalidCreates) throws(() => store.create(bad), TypeError, `invalid create ${JSON.stringify(bad)}`);
throws(() => store.update(1, { name: "  " }), TypeError, "invalid updated name");
throws(() => store.update(1, { stars: [] }), TypeError, "empty updated stars");

const removed = store.remove(1);
deepEqual(removed, { id: 1, name: "Orion Final", stars: ["Bellatrix", "Saiph"] }, "removed snapshot");
removed.stars[0] = "changed after removal";
deepEqual(store.findAll().map((item) => item.id), [2], "remaining creation order");
throws(() => store.findOne(1), RangeError, "removed ID absent");
throws(() => store.remove(1), RangeError, "cannot remove twice");
const third = store.create({ name: "Cygnus", stars: ["Deneb"] });
equal(third.id, 3, "removed and failed IDs are never reused or consumed");

